def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    tcells = [(0,2),(0,3),(1,1),(1,4),(2,0),(2,5),(3,0),(3,5),(4,1),(4,4),(5,2),(5,3)]
    rings = []
    vis = {}
    for c in sorted(set(g.flatten().tolist()) - {bg}):
        comps = components(g == c)
        if max(len(k) for k in comps) < 2:
            continue  # single-pixel noise colour
        ccells = set(zip(*np.where(g == c)))
        vis[c] = len(ccells)
        found = None
        for oy in range(-5, H):
            for ox in range(-5, W):
                pos = {(oy + y, ox + x) for y, x in tcells}
                if ccells <= pos:
                    found = pos
                    break
            if found:
                break
        if found:
            rings.append((c, found))
    # occlusion: c1 visible on a cell shared with c2 => c1 above c2
    below = {c: set() for c, _ in rings}
    for c1, p1 in rings:
        for c2, p2 in rings:
            if c1 == c2:
                continue
            shared = [(y, x) for y, x in p1 & p2 if 0 <= y < H and 0 <= x < W]
            if any(g[y, x] == c1 for y, x in shared):
                below[c1].add(c2)
    incoming = {c: 0 for c in below}
    for c in below:
        for o in below[c]:
            incoming[o] += 1
    order = []
    while len(order) < len(rings):
        ready = [c for c in below if c not in order and incoming[c] == 0]
        if not ready:
            ready = [c for c in below if c not in order]
        ready.sort(key=lambda c: -vis[c])
        c = ready[0]
        order.append(c)
        for o in below[c]:
            incoming[o] -= 1
    out = np.full((6 * len(order), 6), bg, dtype=int)
    emit(out, f"Allocate a {6*len(order)}x6 canvas of background {bg}: one 6x6 band per ring.")
    for i, c in enumerate(order):
        for y, x in tcells:
            out[6 * i + y, x] = c
        emit(out, f"Stamp the complete ring of colour {c} in band {i} (layer {i} from the top).")
    return out
